// src/store/userStore.js
import { reactive, toRefs } from "vue";

// 从 localStorage 中获取用户数据并解析
const storedUserData = localStorage.getItem("userStore");
const initialUser = storedUserData ? JSON.parse(storedUserData) : {};

const state = reactive({
  user: initialUser, // 初始化用户数据
});

// 定义 getters
const getters = {
  user(state) {
    return state.user; // 直接返回用户数据
  },
  userPhoneNumber(state) {
    return state.user ? state.user.phoneNumber : null; // 获取用户电话
  },
  userId(state) {
    return state.user ? state.user.id : null; // 获取用户ID
  },
  userBalance(state) {
    return state.user ? state.user.AccountBalance : null; // 获取用户余额
  },
  userNickname(state) {
    return state.user ? state.user.nickname : "用户"; // 获取用户昵称
  },
  userAvatar(state) {
    return state.user ? state.user.avatar : "/assets/avatar.png"; // 获取用户头像
  },
};

// 导出状态和 getters
export default {
  ...toRefs(state),
  getters,
};
